function m_json($v):string{return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);}function m_hash($v):string{return hash('sha256',is_string($v)?$v:m_json($v));}
