function m_evidence($raw):array{try{$v=json_decode((string)$raw,true,64,JSON_THROW_ON_ERROR);return is_array($v)?$v:[];}catch(Throwable $e){return[];}}function m_source(array $e):array{if(isset($e['source'])&&is_array($e['source']))return$e['source'];if(isset($e['prior_evidence'])&&is_array($e['prior_evidence']))return m_source($e['prior_evidence']);return[];}function m_geo(array $e):array{if(isset($e['geography'])&&is_array($e['geography']))return$e['geography'];if(isset($e['prior_evidence'])&&is_array($e['prior_evidence']))return m_geo($e['prior_evidence']);return[];}
function m_num($v):?float{if($v===null||$v==='')return null;$x=(float)$v;return is_finite($x)&&$x!=0.0?$x:null;}function m_coord(array $s,array $e,string $axis):?float{$keys=$axis==='lat'?['latitude','lat']:['longitude','lon','lng'];foreach($keys as $k)if(array_key_exists($k,$s)&&m_num($s[$k])!==null)return m_num($s[$k]);$g=m_geo($e);foreach($keys as $k)if(array_key_exists($k,$g)&&m_num($g[$k])!==null)return m_num($g[$k]);return null;}
function m_dist($a,$b,$c,$d):?float{$p=[m_num($a),m_num($b),m_num($c),m_num($d)];if(in_array(null,$p,true))return null;$p=array_map('deg2rad',$p);[$a,$b,$c,$d]=$p;$x=sin(($c-$a)/2)**2+cos($a)*cos($c)*sin(($d-$b)/2)**2;return 6371000*2*asin(min(1,sqrt($x)));}
function m_star(array $s):?int{foreach(['category','star','stars','starName','star_name'] as $k){if(!array_key_exists($k,$s))continue;if(preg_match('/(?:^|\D)([1-5])(?:\D|$)/',(string)$s[$k],$m))return(int)$m[1];}return null;}function m_places(array $s,array $e):array{$g=m_geo($e);$vals=[];foreach(['town','region','parent','resort','subregion','subRegion'] as $k){if(isset($s[$k]))$vals[]=$s[$k];if(isset($g[$k]))$vals[]=$g[$k];}$out=[];foreach($vals as $v){$n=m_norm($v);if($n!=='')$out[$n]=1;}return$out;}
