function m_country_by_sha(PDO $db):array{$tmp=[];$sql="SELECT i.catalog_sha256,h.country_id,COUNT(*) n FROM andromeda_hotel_identities i JOIN catalog_hotels h ON h.id=i.local_hotel_id WHERE i.supplier_namespace='andromeda_catalog' AND i.local_hotel_id IS NOT NULL AND h.country_id IN (1,2,4,8,9,10,12,16) GROUP BY i.catalog_sha256,h.country_id";foreach($db->query($sql)->fetchAll(PDO::FETCH_ASSOC)as$r)$tmp[$r['catalog_sha256']][(int)$r['country_id']]=(int)$r['n'];$out=[];foreach($tmp as$sha=>$by){arsort($by);$ids=array_keys($by);if(count($ids)===1||$by[$ids[0]]>($by[$ids[1]]??0)*20)$out[$sha]=(int)$ids[0];}return$out;}
function m_anex_bridge(PDO $db,int $target,array $sourceKeys):bool{if(!$sourceKeys)return false;$sql="SELECT h.api_name,h.xml_name,h.xml_alternate_name FROM anex_hotel_search_mappings m JOIN anex_hotels h ON h.anex_hotel_id=m.anex_hotel_id LEFT JOIN anex_hotel_decisions d ON d.anex_hotel_id=m.anex_hotel_id WHERE m.catalog_hotel_id=? AND m.enabled=1 AND d.anex_hotel_id IS NULL AND NOT EXISTS(SELECT 1 FROM anex_review_pair_exclusions x WHERE x.anex_hotel_id=m.anex_hotel_id AND x.catalog_hotel_id=m.catalog_hotel_id) UNION ALL SELECT h.api_name,h.xml_name,h.xml_alternate_name FROM anex_hotel_decisions d JOIN anex_hotels h ON h.anex_hotel_id=d.anex_hotel_id WHERE d.catalog_hotel_id=? AND d.decision_status='accepted' AND NOT EXISTS(SELECT 1 FROM anex_review_pair_exclusions x WHERE x.anex_hotel_id=d.anex_hotel_id AND x.catalog_hotel_id=d.catalog_hotel_id)";$q=$db->prepare($sql);$q->execute([$target,$target]);$src=array_fill_keys($sourceKeys,1);while($r=$q->fetch(PDO::FETCH_ASSOC))foreach([$r['api_name']??'',$r['xml_name']??'',$r['xml_alternate_name']??'']as$name)foreach(m_keys($name)as$k)if(isset($src[$k]))return true;return false;}
function m_read_selected(PDO $db,bool $lock):array{$ids=array_keys(MATCH_PAIRS);$marks=implode(',',array_fill(0,count($ids),'?'));$sql="SELECT * FROM andromeda_hotel_identities WHERE supplier_namespace=? AND external_hotel_id IN ($marks) ORDER BY external_hotel_id".($lock?' FOR UPDATE':'');$q=$db->prepare($sql);$q->execute(array_merge([MATCH_NAMESPACE],$ids));$out=[];while($r=$q->fetch(PDO::FETCH_ASSOC))$out[(string)$r['external_hotel_id']]=$r;return$out;}
function m_target(PDO $db,int $id,bool $lock):?array{$sql="SELECT h.id,h.country_id,h.name,h.normalized_name,h.region_name,h.subregion_name,h.category,h.is_active,COALESCE(d.latitude,h.latitude) latitude,COALESCE(d.longitude,h.longitude) longitude FROM catalog_hotels h LEFT JOIN catalog_hotel_details d ON d.hotel_id=h.id WHERE h.id=?".($lock?' FOR UPDATE':'');$q=$db->prepare($sql);$q->execute([$id]);$r=$q->fetch(PDO::FETCH_ASSOC);return$r?:null;}
function m_unique_exact(PDO $db,int $country,int $expected,array $sourceKeys):bool{static$cache=[];if(!$sourceKeys)return false;if(!isset($cache[$country])){$index=[];$q=$db->prepare("SELECT h.id,h.name,h.normalized_name FROM catalog_hotels h WHERE h.country_id=? AND h.is_active=1");$q->execute([$country]);while($r=$q->fetch(PDO::FETCH_ASSOC))foreach([$r['name'],$r['normalized_name']]as$name)foreach(m_keys($name)as$k)$index[$k][(int)$r['id']]=1;$q=$db->prepare("SELECT a.hotel_id,a.alias,a.normalized_alias FROM hotel_aliases a JOIN catalog_hotels h ON h.id=a.hotel_id WHERE h.country_id=? AND h.is_active=1");$q->execute([$country]);while($r=$q->fetch(PDO::FETCH_ASSOC))foreach([$r['alias'],$r['normalized_alias']]as$name)foreach(m_keys($name)as$k)$index[$k][(int)$r['hotel_id']]=1;$cache[$country]=$index;}$targets=[];foreach($sourceKeys as$k)foreach(array_keys($cache[$country][$k]??[])as$id)$targets[(int)$id]=1;return count($targets)===1&&isset($targets[$expected]);}
function m_validate(PDO $db,array $row,int $target,array $shaCountry,bool $lock=false):array{$e=m_evidence($row['evidence_json']??'');$s=m_source($e);$sourceNames=array_values(array_filter([$s['name']??'',$s['lName']??'',$s['nameEn']??'',$s['nameRu']??'']));$sourceKeys=[];foreach($sourceNames as$n)foreach(m_keys($n)as$k)$sourceKeys[$k]=1;$sourceKeys=array_keys($sourceKeys);$country=$shaCountry[$row['catalog_sha256']??'']??null;$h=m_target($db,$target,$lock);$reasons=[];if(($row['decision_status']??'')!=='pending'||$row['local_hotel_id']!==null)$reasons[]='source_not_pending_null';if(!$country||!in_array($country,MATCH_CORE_COUNTRIES,true))$reasons[]='country_authority_missing';if(!$h||(int)$h['is_active']!==1)$reasons[]='target_inactive_missing';if($h&&$country&&(int)$h['country_id']!==$country)$reasons[]='country_mismatch';$unique=$country&&$h?m_unique_exact($db,$country,$target,$sourceKeys):false;if(!$unique)$reasons[]='not_unique_exact_current';$places=m_places($s,$e);$targetPlaces=[];if($h)foreach([$h['region_name'],$h['subregion_name']]as$v){$n=m_norm($v);if($n!=='')$targetPlaces[$n]=1;}$placeMatch=(bool)array_intersect_key($places,$targetPlaces);$slat=m_coord($s,$e,'lat');$slon=m_coord($s,$e,'lon');$dist=$h?m_dist($slat,$slon,$h['latitude'],$h['longitude']):null;if($dist!==null&&$dist>5000)$reasons[]='coordinate_conflict_gt5km';$sourceStar=m_star($s);$targetStar=$h&&$h['category']!==null?(int)$h['category']:null;if($sourceStar&&$targetStar&&$sourceStar!==$targetStar)$reasons[]='explicit_star_mismatch';$bridge=$h?m_anex_bridge($db,$target,$sourceKeys):false;$independent=$placeMatch||($dist!==null&&$dist<=1000)||$bridge;if(!$independent)$reasons[]='independent_evidence_missing';return['ok'=>$reasons===[],'reasons'=>$reasons,'country_id'=>$country,'source_names'=>$sourceNames,'source_keys'=>$sourceKeys,'place_match'=>$placeMatch,'distance_m'=>$dist===null?null:round($dist,1),'anex_bridge'=>$bridge,'source_star'=>$sourceStar,'target_star'=>$targetStar,'target_name